const BASE='https://usximvurnararrwsnbit.supabase.co';
const KEY='sb_publishable_SI8yLXOZL_XXSmm8F7Xvnw_YoJcB-Yh';
const SECURITY={'Cache-Control':'no-store','X-Content-Type-Options':'nosniff','Referrer-Policy':'no-referrer','X-Frame-Options':'DENY','Content-Security-Policy':"default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self' blob: data: https://usximvurnararrwsnbit.supabase.co; connect-src 'self'; object-src 'none'; base-uri 'none'; frame-ancestors 'none'; form-action 'self'"};
const cookie=(name,value,age)=>`${name}=${value}; HttpOnly; Secure; SameSite=Lax; Path=/; Max-Age=${age}`;
const json=(data,status=200,cookies=[])=>{const headers=new Headers({...SECURITY,'Content-Type':'application/json'});for(const c of cookies)headers.append('Set-Cookie',c);return new Response(JSON.stringify(data),{status,headers})};
async function api(request){
 if(request.method!=='POST')return json({error:'Metoden stöds inte.'},405);
 if(request.headers.get('origin')!==new URL(request.url).origin)return json({error:'Ogiltig förfrågan.'},403);
 if(Number(request.headers.get('content-length')||0)>7500000)return json({error:'För stor förfrågan.'},413);
 try{
 const text=await request.text();if(text.length>7500000)return json({error:'För stor förfrågan.'},413);const b=JSON.parse(text);
 const c=Object.fromEntries((request.headers.get('cookie')||'').split(';').map(x=>x.trim().split('=')));
 let access=c.pvol_access||'',refresh=c.pvol_refresh||'',updated=false;
 if(refresh&&!['login','accept','inviteInfo'].includes(b.action)){
 let exp=0;try{exp=JSON.parse(atob(access.split('.')[1].replace(/-/g,'+').replace(/_/g,'/'))).exp}catch{}
 if(exp*1000<Date.now()+60000){const r=await fetch(BASE+'/auth/v1/token?grant_type=refresh_token',{method:'POST',headers:{apikey:KEY,'Content-Type':'application/json'},body:JSON.stringify({refresh_token:refresh})});const d=await r.json();if(!r.ok)return json({error:'Logga in igen.'},401,[cookie('pvol_access','',0),cookie('pvol_refresh','',0)]);access=d.access_token;refresh=d.refresh_token;updated=true;}
 }
 const r=await fetch(BASE+'/functions/v1/pvol-api',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+(access||KEY),'x-forwarded-for':request.headers.get('cf-connecting-ip')||'unknown'},body:JSON.stringify(b)});
 const d=await r.json();if(d.session){access=d.session.access_token;refresh=d.session.refresh_token;updated=true;delete d.session;d.ok=true;}
 const cookies=[];if(b.action==='logout'||d.reauth){cookies.push(cookie('pvol_access','',0),cookie('pvol_refresh','',0))}else if(updated){cookies.push(cookie('pvol_access',access,3600),cookie('pvol_refresh',refresh,2592000))}
 return json(d,r.status,cookies);
 }catch{return json({error:'Tjänsten kunde inte nås. Försök igen.'},500)}
}
