const almanacCache=new Map();
async function almanac(request){const month=new URL(request.url).searchParams.get('month');if(!/^20[0-9]{2}-(0[1-9]|1[0-2])$/.test(month||''))return json({error:'Ogiltig månad.'},400);const cached=almanacCache.get(month);if(cached&&cached.expires>Date.now())return json({days:cached.days});try{const r=await fetch('https://sholiday.faboul.se/dagar/v2.1/'+month.replace('-','/'),{signal:AbortSignal.timeout(8000),cf:{cacheTtl:86400,cacheEverything:true}});if(!r.ok)throw Error();const data=await r.json();if(!Array.isArray(data.dagar))throw Error();const days=data.dagar.map(d=>({date:d.datum,names:Array.isArray(d.namnsdag)?d.namnsdag:[],red:d['röd dag']==='Ja'}));almanacCache.set(month,{days,expires:Date.now()+86400000});if(almanacCache.size>36)almanacCache.delete(almanacCache.keys().next().value);return json({days})}catch{const [y,m]=month.split('-').map(Number),days=Array.from({length:new Date(Date.UTC(y,m,0)).getUTCDate()},(_,i)=>{const date=month+'-'+String(i+1).padStart(2,'0');return {date,names:NAMEDAYS[date.slice(5)]||[],red:false}});return json({days})}}
